import index from './honourLevels.json';
import { chapterIndexOf } from './chapters';

// Mine elements each level consumes, generated by scripts/export-honour-levels.mjs so
// the museum and collection never build every level configuration to show them.
export const levelHonourElements = (levelId) => index[levelId] ?? {};

// The levels and chapter range (1-based, as shown in the museum) holding an element.
export function elementLevels(elementId) {
  const levels = Object.keys(index)
    .map(Number)
    .filter((id) => index[id][elementId] > 0)
    .sort((a, b) => a - b);
  return {
    levels,
    pieces: levels.reduce((sum, id) => sum + index[id][elementId], 0),
    chapters: levels.length
      ? [chapterIndexOf(levels[0]) + 1, chapterIndexOf(levels.at(-1)) + 1]
      : null,
  };
}
